window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[40]={"id":"040","numero":40,"titre":"Algies pelviennes chez la femme","objectifs":[{"id":"40-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la douleur pelvienne aiguë (DPA) et chronique (DPC)","contenu":"<div class=\"notion-course\"><p>Les <span>algies pelviennes</span> regroupent l’ensemble des <strong>symptômes douloureux, spontanés ou provoqués</strong>, de la région <strong><span><span class=\"nc-blue_bg\">hypogastre</span></span></strong> et/ou des <strong><span><span class=\"nc-blue_bg\">fosses iliaques</span></span></strong> droite et gauche. Elles sont l’un des motifs de consultation gynécologique les plus fréquents.</p>\n\n      <table>\n        <thead>\n          <tr><th>Forme</th><th><span>Évolution</span></th><th>Caractéristiques sémiologiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Douleur pelvienne aiguë (DPA)</strong></td>\n            <td><span><span class=\"nc-pink nc-bold\">&lt; 1 mois</span></span> · début récent · <span>évolution</span> rapide</td>\n            <td>Douleur <strong>subite</strong>, type <em>coup de poignard</em>, <span class=\"nc-red nc-bold\">torsion</span>, colique, <span>irradiation</span> possible</td>\n          </tr>\n          <tr>\n            <td><strong>Douleur pelvienne chronique (DPC)</strong></td>\n            <td><span><span class=\"nc-pink nc-bold\">&gt; 6 mois</span></span> · permanente ou intermittente · <strong>cyclique ou non</strong></td>\n            <td><span>Pesanteur</span>, tiraillement, picotement · ± rythmée par le cycle menstruel</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p>3 voies d’innervation principales du <span class=\"nc-blue_bg\">pelvis</span> structurent la <span>topographie</span> de la douleur :</p>\n      <ul>\n        <li><strong>Plexus pelvien</strong> (<span class=\"nc-blue_bg\">vagin</span>, col, isthme utérin, ligaments utéro-sacrés, cul-de-sac recto-utérin, <span class=\"nc-blue_bg\">bas uretères</span>, <span class=\"nc-blue_bg\">trigone vésical</span>, recto-sigmoïde) → douleur <strong><span class=\"nc-red nc-bold\">sacrée</span> ou <span class=\"nc-red nc-bold\">périnéale</span></strong></li>\n        <li><strong>Plexus hypogastrique</strong> (<span class=\"nc-yellow_bg\">corps utérin</span>, <span class=\"nc-yellow_bg\">1/3 proximal des trompes</span>, <span class=\"nc-yellow_bg\">ligament large</span>, <span class=\"nc-yellow_bg\">calotte vésicale</span>) → douleur <strong>hypogastrique</strong></li>\n        <li><strong>Plexus aortique</strong> (<span class=\"nc-purple_bg\">ovaires</span>, <span class=\"nc-purple_bg\">portion distale des trompes</span>, uretères rétro-ligamentaires) → douleur <strong><span><span class=\"nc-blue_bg\">fosses iliaques</span></span>, <span class=\"nc-purple_bg\">flancs</span> et <span class=\"nc-purple_bg\">fosses lombaires</span></strong></li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Une douleur <span class=\"nc-red nc-bold\">pelvienne</span> aiguë <em>n’a pas d’étiologie retrouvée dans <span>25–50 %</span> des cas</em>. Pour les douleurs <strong>chroniques</strong>, les causes par ordre décroissant sont : <strong><span class=\"nc-orange_bg\">digestives</span> &gt; <span class=\"nc-orange_bg\">urinaires</span> &gt; <span class=\"nc-orange_bg\">gynécologiques</span></strong>.\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Endometriose202025_imagerie_recommandations_ca.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Imagerie de l’endométriose, 2025</a></li></ul></details>","frequence":0},{"id":"40-2","rang":"A","rubrique":"Étiologies","titre":"Connaître les étiologies des DPA","contenu":"<div class=\"notion-course\"><p>Les étiologies des <span>douleurs pelviennes aiguës (DPA)</span> sont classées en <strong><span <span=\"\">&gt;6</span> grands cadres</strong> à mémoriser de façon systématique pour orienter l’interrogatoire et le bilan.</p>\n\n      <table>\n        <thead>\n          <tr><th>Cadre</th><th>Étiologies</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Post-<span>grossesse</span></strong></td>\n            <td>\n              <span>GEU</span> · <span>fausse couche spontanée</span> · rétention post-FC · <span>endométrite du post-partum</span> ou post-abortum · complication du corps jaune gestationnel (<span>hémorragique</span>, kyste et ses complications)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Infectieuses</strong></td>\n            <td>\n              <span>IGH</span> (<span>salpingite</span>, endométrite, <span><span class=\"nc-red nc-bold\">pelvipéritonite</span></span>, <span><span class=\"nc-red nc-bold\">abcès</span></span><span class=\"nc-red nc-bold\"> tubo-ovarien</span>) · <span>appendicite aiguë</span> · <span>PNA</span> · IU basse\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Annexielles</strong></td>\n            <td>\n              <span><span class=\"nc-red nc-bold\">Torsion</span> d’annexe</span> · <span class=\"nc-red_bg\">complications de kyste ovarien</span> (hémorragie intra-kystique, <span>rupture</span>, <span class=\"nc-red nc-bold\">torsion</span>) · dysovulation\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Sur présence d’un fibrome</strong></td>\n            <td>\n              <span>Nécrobiose aiguë</span> · <span class=\"nc-red nc-bold\">torsion</span> d’un myome sous-séreux pédiculé · accouchement d’un myome sous-muqueux par le col utérin\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Urologique</strong></td>\n            <td>\n              <span><span class=\"nc-blue_bg\">Colique néphrétique</span></span> · <span>PNA</span> · IU basse\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Rares</strong></td>\n            <td>\n              Sacro-iléite <span>bactérienne</span> · ostéite · anévrisme de l’artère iliaque · infection d’un kyste de l’ouraque\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span>Grossesse</span> normale · 25 — GEU · 41 — Endométriose · 158 — <span>Sepsis</span> · 354 — Syndrome occlusif (DD appendicite)</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Endometriose202025_imagerie_recommandations_ca.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Imagerie de l’endométriose, 2025</a></li></ul></details>","frequence":0},{"id":"40-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie des DPA et des DPC","contenu":"<div class=\"notion-course\"><p>La <span>physiopathologie</span> diffère entre douleur aiguë (mécanisme lésionnel direct) et douleur chronique (mécanismes multiples intriqués).</p>\n\n      <h4>Douleur pelvienne aiguë — voies de la douleur</h4>\n      <p>L’interprétation sémiologique est <strong>difficile</strong> : proximité des organes pelviens + innervation commune. Trois plexus efférents structurent la topographie :</p>\n      <table>\n        <thead>\n          <tr><th>Plexus</th><th>Organes</th><th>Topographie de la douleur</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Hypogastrique</strong></td>\n            <td><span class=\"nc-yellow_bg\">Corps utérin</span>, <span class=\"nc-yellow_bg\">1/3 proximal des trompes</span>, <span class=\"nc-yellow_bg\">ligament large</span>, <span class=\"nc-yellow_bg\">calotte vésicale</span></td>\n            <td>Hypogastrique</td>\n          </tr>\n          <tr>\n            <td><strong>Aortique</strong></td>\n            <td><span class=\"nc-purple_bg\">Ovaires</span>, <span class=\"nc-purple_bg\">portion distale des trompes</span>, uretères rétro-ligamentaires</td>\n            <td><span class=\"nc-purple_bg\">Flancs</span>, <span><span class=\"nc-blue_bg\">fosses iliaques</span></span>, <span class=\"nc-purple_bg\">fosses lombaires</span></td>\n          </tr>\n          <tr>\n            <td><strong>Pelvien</strong></td>\n            <td><span class=\"nc-blue_bg\">Vagin</span>, col/isthme, ligaments utéro-sacrés, <span class=\"nc-blue_bg\">bas uretères</span>, <span class=\"nc-blue_bg\">trigone vésical</span>, <span class=\"nc-blue_bg\">cul-de-sac de Douglas</span>, recto-sigmoïde</td>\n            <td><strong><span class=\"nc-red nc-bold\">Sacrée</span></strong> et <strong><span class=\"nc-red nc-bold\">périnéale</span></strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Douleur pelvienne chronique — hypothèses physiopathologiques</h4>\n      <ul>\n        <li><strong>Hypothèse <span>ischémique</span></strong> : les <span><span class=\"nc-pink nc-bold\">prostaglandines</span></span> ↗ les <span class=\"nc-blue_bg\">contractions utérines</span> → ischémie utérine relative douloureuse</li>\n        <li><strong>Hypothèse spasmodique</strong> : les <span>prostaglandines</span> ↗ le tonus du sphincter cervico-isthmique, désynchronisé du cycle → retard d’ouverture du col → gêne à l’écoulement menstruel</li>\n        <li><strong>Hypothèse congestive</strong> : <span class=\"nc-red nc-bold\">stase</span> <span class=\"nc-red nc-bold\">pelvienne</span> (<span><span class=\"nc-blue_bg\">constipation</span></span>, faiblesse musculaire <span class=\"nc-red nc-bold\">pelvienne</span>, <span class=\"nc-blue_bg\">varices pelviennes</span>)</li>\n        <li><strong>Facteurs hormonaux</strong> : déséquilibre œstroprogestatif en phase lutéale (hyperœstrogénie relative) → congestion ; pics et chutes d’œstrogènes expliquent les douleurs intermenstruelles et prémenstruelles</li>\n        <li><strong>Facteurs psychologiques</strong> : zone pelvi-génitale = site fréquent de somatisation → rôle dans le <strong>maintien</strong> de la douleur chronique</li>\n      </ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Endometriose202025_imagerie_recommandations_ca.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Imagerie de l’endométriose, 2025</a></li></ul></details>","frequence":0},{"id":"40-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaitre les élements de l’interrogatoire et de l’examen clinique utiles au diagnostic des DPA","contenu":"<div class=\"notion-course\"><p>La <span>démarche diagnostique</span> repose sur un interrogatoire structuré, différent selon que la douleur est aiguë ou chronique, et un examen physique adapté (abdominal + spéculum + <span>TV</span>).</p>\n\n      <h4>Interrogatoire</h4>\n\n      <table>\n        <thead>\n          <tr><th>Axe</th><th>Douleur aiguë</th><th>Douleur chronique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Date d’apparition</strong></td>\n            <td>Récente (<span>&lt; 1 mois</span>), <strong>subite</strong></td>\n            <td>Moins récente, <span>évolution</span> <span>&gt; 6 mois</span></td>\n          </tr>\n          <tr>\n            <td><strong><span>Évolution</span></strong></td>\n            <td>Rapide</td>\n            <td>Permanente ou intermittente</td>\n          </tr>\n          <tr>\n            <td><strong>Apparition dans le cycle</strong></td>\n            <td>—</td>\n            <td>Prémenstruel, <strong><span>dysménorrhée</span></strong>, intermenstruel</td>\n          </tr>\n          <tr>\n            <td><strong>Type</strong></td>\n            <td>Coup de poignard, torsion, colique, <span>irradiation</span></td>\n            <td><span>Pesanteur</span>, tiraillement, picotement, irradiation</td>\n          </tr>\n          <tr>\n            <td><strong>Signes associés</strong></td>\n            <td>\n              Date des dernières règles<br>\n              <span>Syndrome <span>infectieux</span></span><br>\n              <span>Nausées</span>, <span>vomissements</span>, SFU<br>\n              Signes de <span>grossesse</span>, <span class=\"nc-blue nc-bold\">métrorragies</span>, position <span>antalgique</span>\n            </td>\n            <td>\n              <span>Céphalées</span>, lombalgie, diarrhées, <span>constipation</span><br>\n              <span class=\"nc-blue nc-bold\">Métrorragies</span>, <span>dyspareunies</span>, infertilité\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Antécédents</strong></td>\n            <td>\n              GOB, chirurgicaux<br>\n              Contraception · conduite à risque (IST)\n            </td>\n            <td>\n              <span class=\"nc-orange_bg\">Gynécologiques</span>, obstétricaux, chirurgicaux, CO<br>\n              Retentissement sur la qualité de vie\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Examen clinique</h4>\n\n      <ul>\n        <li><strong>Inspection · palpation abdominale</strong> : recherche de défense, contracture, <span>masse</span></li>\n        <li><strong>Spéculum</strong> : <span>leucorrhées</span>, métrorragies, aspect du col</li>\n        <li><strong>Toucher vaginal (<span>TV</span>)</strong> :\n          <ul>\n            <li>Douleur à la mobilisation utérine (orientation <span class=\"nc-yellow_bg\">IGH</span>)</li>\n            <li><span>Masse</span> latéro-utérine (GEU, kyste compliqué)</li>\n            <li>Sensibilité du cul-de-sac de Douglas (hémopéritoine, IGH)</li>\n            <li><span>Hypersensibilité</span> de la paroi vaginale antérieure (<strong>syndrome douloureux vésical</strong>)</li>\n          </ul>\n        </li>\n        <li><strong><span>BU</span></strong> systématique : <span>nitrites</span>, <span>leucocytes</span>, <span>hématurie</span></li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Toute femme en âge de procréer avec une douleur <span class=\"nc-red nc-bold\">pelvienne</span> aiguë doit avoir : <strong>β-hCG plasmatique + <span>BU</span> + écho <span class=\"nc-red nc-bold\">pelvienne</span></strong> en <span>première ligne</span> — c’est la triade qui élimine les 4 urgences.\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Endometriose202025_imagerie_recommandations_ca.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Imagerie de l’endométriose, 2025</a></li></ul></details>","frequence":0},{"id":"40-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires biologiques","contenu":"<div class=\"notion-course\"><p>Toute femme en âge de procréer avec une <span>douleur pelvienne aiguë</span> bénéficie d’un bilan <span>biologique</span> de <strong>1ʳᵉ intention</strong> centré sur l’élimination des urgences.</p>\n\n      <div class=\"callout callout-info\">\n        <strong>Réflexe 1ʳᵉ intention.</strong> <span><span class=\"nc-pink_bg\">β-hCG</span></span> + <span>NFS</span> + <span>CRP</span> + <span>BU</span> + <span>prélèvements vaginaux</span>/endocervicaux (si suspicion d’<span class=\"nc-red\">IGH</span>).\n      </div>\n\n      <table>\n        <thead>\n          <tr><th>Examen</th><th>Intérêt · interprétation</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>β-hCG</span></strong></td>\n            <td>Indispensable chez toute femme en période d’activité génitale · <strong>si négatif → élimine une GEU</strong></td>\n          </tr>\n          <tr>\n            <td><strong><span>NFS</span></strong></td>\n            <td>\n              <strong>Anémie</strong> → hémopéritoine<br>\n              Hyperleucocytose : quasi-constante dans l’appendicite · <strong>fréquemment absente dans l’<span class=\"nc-brown_bg\">IGH</span> simple</strong> (si présente → forme compliquée) · fréquente sur nécrobiose · rare sur <span class=\"nc-brown_bg\">torsion d’annexe</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>CRP</span></strong></td>\n            <td><span>Syndrome <span>inflammatoire</span></span> → cause infectieuse (IGH, appendicite) · <span>CRP</span> très élevée + IGH → évoque un <span><span class=\"nc-red nc-bold\">abcès tubo-ovarien</span></span></td>\n          </tr>\n          <tr>\n            <td><strong><span>Bandelette urinaire</span></strong></td>\n            <td>Nitrites + <span>leucocyturie</span> → <strong>infection urinaire</strong> · <span>hématurie</span> → <span class=\"nc-blue_bg\">colique néphrétique</span> (impose une écho des voies urinaires)</td>\n          </tr>\n          <tr>\n            <td><strong>Bactériologie</strong></td>\n            <td>Prélèvements vaginaux + endocervicaux : <strong>indispensables si suspicion d’<span class=\"nc-red\">IGH</span></strong> (<span>gonocoque</span>, <em>C. trachomatis</em>, <em>M. genitalium</em>) · ablation + mise en culture du DIU si <span class=\"nc-red\">IGH</span></td>\n          </tr>\n          <tr>\n            <td><strong><span>Biopsie d’endomètre</span></strong><br><em>(2ᵈᵉ intention)</em></td>\n            <td>Doute <span><span class=\"nc-red\">grossesse</span></span><span class=\"nc-red\"> arrêtée</span> / <span class=\"nc-red\">GEU</span> → présence de <em>villosités choriales</em> élimine la <span class=\"nc-red\">GEU</span> · suspicion d’<span class=\"nc-red\">IGH</span> paucisymptomatique → <span class=\"nc-blue_bg\">signes histologiques d’endométrite</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège ⭐.</strong> <em>Aucun examen <span>biologique</span> n’affirme le syndrome douloureux vésical chronique</em> : l’<span>ECBU</span> y est <strong>stérile</strong> (<span>leucocyturie</span> possible) — le diagnostic est endoscopique (<span>cystoscopie</span>), traité en onglet « Astuces PU ».\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Endometriose202025_imagerie_recommandations_ca.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Imagerie de l’endométriose, 2025</a></li></ul></details>","frequence":1},{"id":"40-6","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les urgences chirurgicales devant une douleur aiguë pelvienne","contenu":"<div class=\"notion-course\"><p>Devant toute <span>douleur pelvienne aiguë chez une femme</span>, <strong>5 diagnostics</strong> doivent être évoqués systématiquement car ils engagent le <span>pronostic vital et/ou fonctionnel</span> :</p>\n\n      <ol>\n        <li><strong>GEU</strong> (<span>grossesse</span> extra-utérine)</li>\n        <li><strong>Torsion d’annexe</strong></li>\n        <li><strong><span>Rupture</span> <span>hémorragique</span> de kyste</strong> (<span class=\"nc-red nc-bold\">hémopéritoine</span>)</li>\n        <li><strong>IGH</strong> (infection génitale haute)</li>\n        <li><strong>Appendicite aiguë</strong></li>\n      </ol>\n\n      <table>\n        <thead>\n          <tr><th>Entité</th><th>Interrogatoire — éléments clés</th><th>Examen clinique</th><th>Examens complémentaires</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>GEU</span></strong><br><em>Nidation embryonnaire hors cavité utérine (<span>2 %</span> des grossesses)</em></td>\n            <td>\n              Douleurs pelviennes aiguës + <span class=\"nc-blue nc-bold\">métrorragies</span> <em>« sépia »</em> + retard de règles<br>\n              Signes sympathiques de <span>grossesse</span> (<span>nausées</span>, tension mammaire)<br>\n              FDR : <span>ATCD <span class=\"nc-brown_bg\">IGH</span>/chirurgie</span>, <span>tabagisme</span> actif, FIV\n            </td>\n            <td>\n              Défense ± contracture<br>\n              <span>TV</span> : douleur provoquée + <span>masse</span> latéro-utérine, palpation du cul-de-sac de Douglas douloureuse<br>\n              <span>Signes de gravité</span> : <span><span class=\"nc-red nc-bold\">hémopéritoine</span></span>, scapulalgie, anomalies HDM\n            </td>\n            <td>\n              β-hCG <span>&gt; 1500 UI/L</span><br>\n              Écho endovaginale : <strong>vacuité utérine</strong>, endomètre épais, présence du corps jaune, épanchement Douglas, <span class=\"nc-red nc-bold\">hémopéritoine</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-red nc-bold\">Torsion</span> d’annexe</span></strong><br><em>Ovaire ou ovaire + trompe (rare sur trompe saine)</em></td>\n            <td>\n              Douleur <em>brutale, en coup de poignard</em><br>\n              Troubles digestifs (<span>nausées</span>, <span>vomissements</span>, arrêt des gaz)<br>\n              ATCD de kyste ovarien connu\n            </td>\n            <td>\n              Défense abdominale ± météorisme<br>\n              <span>TV</span> : douleur latéro-utérine <span class=\"nc-red nc-bold\">unilatérale</span> <strong>très douloureuse au niveau du collet</strong>\n            </td>\n            <td>\n              Écho <span class=\"nc-red nc-bold\">pelvienne</span> : ovaire augmenté de taille ± kyste associé, <strong>anomalies de vascularisation</strong> (disparition du pédicule ovarien au <span>Doppler</span>)\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Rupture</span> <span>hémorragique</span> de kyste</strong><br><em><span><span>Pronostic</span> vital</span> engagé</em></td>\n            <td>\n              Douleurs brutales, intenses ± <span>scapulalgie</span><br>\n              Gravité : instabilité HDM<br>\n              ATCD de kyste ovarien\n            </td>\n            <td>\n              Défense abdominale ± contracture<br>\n              <span>TV</span> : douleur diffuse, cul-de-sac de Douglas comblé\n            </td>\n            <td>\n              Écho <span class=\"nc-red nc-bold\">pelvienne</span> : <strong>kyste ovarien + <span class=\"nc-red nc-bold\">hémopéritoine</span></strong><br>\n              <span>NFS</span> : anémie\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>IGH</span></strong><br><em>Salpingite, endométrite, <span><span class=\"nc-red nc-bold\">abcès</span></span><span class=\"nc-red nc-bold\"> tubo-ovarien</span></em></td>\n            <td>\n              Douleurs modérées d’installation lente (évocatrice si <span><span class=\"nc-pink nc-bold\">&gt; 4 jours</span></span>) ± SFU ± <span>irradiation</span> lombaire ou hypocondre droit<br>\n              <span>Syndrome <span>infectieux</span></span><br>\n              Ténesme → rechercher <strong><span><span class=\"nc-red nc-bold\">abcès</span></span><span class=\"nc-red nc-bold\"> tubo-ovarien</span></strong><br>\n              FDR : rapports non protégés, multiples partenaires, gestes récents\n            </td>\n            <td>\n              <span>Irritation péritonéale</span> : défense <span><span class=\"nc-blue_bg\">hypogastre</span></span>/hypocondre droit (<strong><span>syndrome de Fitz</span>-Hugh-Curtis</strong>)<br>\n              Leucorrhées abondantes, épaisses, jaunâtres ± purulentes<br>\n              <span class=\"nc-blue nc-bold\">Métrorragies</span><br>\n              <span>TV</span> : douloureux ++ à la mobilisation utérine et au cul-de-sac de Douglas, douleur <span class=\"nc-red nc-bold\">bilatérale</span> à la palpation des annexes\n            </td>\n            <td>\n              <span>NFS</span> : <span>SIB</span><br>\n              Bactériologie : recherche d’IST (<span>gonocoque</span>, <em>C. trachomatis</em>, <em>M. genitalium</em>)<br>\n              Écho : <span><span>critères de</span> gravité</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Appendicite aiguë</span></strong><br><em>DD chirurgical majeur, surtout à droite</em></td>\n            <td>\n              Douleur débutant en épigastre/péri-ombilical puis <strong>migrant en FID</strong><br>\n              <span>Nausées</span>, <span>vomissements</span>, fébricule<br>\n              <span>Diarrhée</span> rare\n            </td>\n            <td>\n              <strong>Langue saburrale</strong>, défense FID<br>\n              Signe de <strong>Rovsing</strong> (douleur FID à la palpation de la FIG)<br>\n              Signe de <strong>Blumberg</strong> (douleur à la décompression)<br>\n              <strong>Psoïtis</strong>\n            </td>\n            <td>\n              <span>NFS</span> : hyperleucocytose quasi-constante · <span>CRP</span> ↗<br>\n              Écho : <span>diamètre</span> appendiculaire <span>&gt; 6 mm</span>, paroi <span>&gt; 3 mm</span>, appendice incompressible, épanchement FID\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Une <em>douleur <span class=\"nc-red nc-bold\">pelvienne</span> aiguë chez une femme en âge de procréer = β-hCG en <span>urgence</span></em>, quel que soit le contexte contraceptif allégué. Pas de β-hCG = pas de diagnostic.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 25 — GEU · 158 — <span>Sepsis</span> · 354 — Syndrome occlusif (appendicite)</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Endometriose202025_imagerie_recommandations_ca.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Imagerie de l’endométriose, 2025</a></li></ul></details>","frequence":1},{"id":"40-7","rang":"A","rubrique":"Définition","titre":"Savoir distinguer les douleurs chroniques des douleurs aiguës","contenu":"<div class=\"notion-course\"><p>La distinction <span>aiguë / chronique</span> repose avant tout sur la <strong>durée d’<span>évolution</span></strong> et conditionne toute la démarche (<span>urgence</span> <span>vs</span> bilan ambulatoire).</p>\n\n      <table>\n        <thead>\n          <tr><th>Critère</th><th>Douleur pelvienne aiguë (DPA)</th><th>Douleur pelvienne chronique (DPC)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Durée</strong></td>\n            <td><span>&lt; 1 mois</span></td>\n            <td><span>&gt; 6 mois</span></td>\n          </tr>\n          <tr>\n            <td><strong>Installation</strong></td>\n            <td>Subite, récente</td>\n            <td>Progressive, ancienne · <strong>cyclique ou non</strong></td>\n          </tr>\n          <tr>\n            <td><strong><span>Évolution</span></strong></td>\n            <td>Rapide</td>\n            <td>Permanente ou intermittente</td>\n          </tr>\n          <tr>\n            <td><strong>Type</strong></td>\n            <td>Coup de poignard, torsion, colique</td>\n            <td><span>Pesanteur</span>, tiraillement, picotement</td>\n          </tr>\n          <tr>\n            <td><strong>Enjeu</strong></td>\n            <td><span>Éliminer une urgence</span> (<span class=\"nc-orange_bg\">GEU</span>, <span class=\"nc-red nc-bold\">torsion</span>, IGH, appendicite)</td>\n            <td>Retentissement sur la qualité de vie · <span class=\"nc-red nc-bold\">errance diagnostique</span> fréquente</td>\n          </tr>\n          <tr>\n            <td><strong>Causes dominantes</strong></td>\n            <td>Gynéco / obstétricales / chirurgicales aiguës</td>\n            <td><span class=\"nc-orange_bg\">Digestives</span> &gt; <span class=\"nc-orange_bg\">urinaires</span> &gt; <span class=\"nc-orange_bg\">gynécologiques</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Une DPC peut se <em>décompenser en aigu</em> (ex. <span class=\"nc-orange_bg\">endométriose</span>, <span class=\"nc-red nc-bold\">torsion</span> sur kyste connu) : un <span>terrain</span> chronique n’élimine jamais une <span>urgence</span> surajoutée.\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Endometriose202025_imagerie_recommandations_ca.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Imagerie de l’endométriose, 2025</a></li></ul></details>","frequence":0},{"id":"40-8","rang":"A","rubrique":"Définition","titre":"Connaître les principales étiologies des DPC","contenu":"<div class=\"notion-course\"><ul><li>Douleurs cycliques : dysménorrhées primaires ou secondaires (<span class=\"nc-orange_bg\">endométriose</span>, adénomyose, obstacle cervical), syndrome prémenstruel et douleur ovulatoire selon contexte.</li><li>Douleurs non cycliques : <span class=\"nc-orange_bg\">endométriose</span>, séquelles d’infection <span class=\"nc-red nc-bold\">pelvienne</span>, pathologie urinaire ou digestive, musculosquelettique et du plancher pelvien ; plusieurs mécanismes peuvent coexister.</li><li>Évaluer symptômes associés, retentissement sexuel, urinaire, digestif et quotidien, traitements antérieurs et facteurs psychosociaux avec respect du consentement.</li><li>L’absence de lésion visible ne permet pas de qualifier automatiquement la douleur de psychogène. Sensibilisation et douleur nociplastique peuvent participer ; une approche multidisciplinaire est utile.</li><li>Toute modification brutale ou signe d’alarme impose de reprendre la démarche de douleur aiguë. Le schéma historique LiSA est transcrit avec cette correction explicite.</li></ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Endometriose202025_imagerie_recommandations_ca.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Imagerie de l’endométriose, 2025</a></li></ul></details>","frequence":0},{"id":"40-9","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les indications des examens d’imagerie devant une algie pelvienne chez la femme","contenu":"<div class=\"notion-course\"><p>La hiérarchisation des examens dépend du contexte (aigu <span>vs</span> chronique) et de l’orientation clinique. La règle EDN : <strong>β-hCG + <span>BU</span> + écho pelvienne</strong> pour toute douleur aiguë chez une femme en âge de procréer.</p>\n\n      <table>\n        <thead>\n          <tr><th>Examen</th><th>Indications · résultats à interpréter</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span><span class=\"nc-blue_bg\">Échographie</span> pelvienne</span></strong><br><em>(examen-clé de 1ʳᵉ intention)</em></td>\n            <td>\n              <span>À réaliser en urgence</span> si instabilité HDM ou suspicion d’<span class=\"nc-red nc-bold\">hémopéritoine</span><br>\n              <strong>Voie abdominale + endovaginale</strong> (sauf vierge → abdominale seule)<br>\n              <span class=\"nc-orange_bg\">GEU</span> : <span>vacuité utérine, masse latéro-utérine, épanchement de Douglas</span><br>\n              <span class=\"nc-red nc-bold\">Torsion</span> : ovaire augmenté ± kyste, <span>arrêt des flux au Doppler</span><br>\n              <span class=\"nc-brown_bg\">IGH</span> : <span class=\"nc-blue_bg\">épaississement de la paroi tubaire</span>, épanchement intra-tubaire, <span><span class=\"nc-red nc-bold\">abcès tubo-ovarien</span></span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Écho des voies urinaires</strong></td>\n            <td>Indiquée si <span>hématurie</span> à la <span>BU</span> → recherche de <span class=\"nc-blue_bg\">colique néphrétique</span> / dilatation</td>\n          </tr>\n          <tr>\n            <td><strong><span>TDM</span> abdomino-pelvien</strong></td>\n            <td>Si doute entre <strong><span class=\"nc-brown_bg\">IGH</span> et appendicite</strong>, ou recherche d’une complication (<span>abcès</span>)</td>\n          </tr>\n          <tr>\n            <td><strong><span>IRM</span> pelvienne</strong></td>\n            <td>Doutes diagnostiques persistants · <strong>femme enceinte</strong> (pas d’<span>irradiation</span>)</td>\n          </tr>\n          <tr>\n            <td><strong><span>Cœlioscopie</span></strong><br><em>(diagnostique + thérapeutique)</em></td>\n            <td>Si doute diagnostique persistant ou indication chirurgicale (torsion, GEU, ATO)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> <em>Pas d’imagerie systématique dans le syndrome douloureux vésical chronique</em> (déplacé dans l’onglet « Astuces PU &amp; Pièges ») — l’examen de référence est la <strong><span>cystoscopie</span></strong>, pas l’écho ni le <span>scanner</span>.\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Endometriose202025_imagerie_recommandations_ca.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Imagerie de l’endométriose, 2025</a></li></ul></details>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Évaluation hémodynamique <span class=\"q\">— 1er réflexe systématique</span></strong></p><ul><li><span class=\"kw-alerte\">Instabilité hémodynamique</span> (<span class=\"kw-clinique\">tachycardie</span> précédant la <span class=\"kw-clinique\">chute de PA</span>) évoque un <span class=\"kw-def\">hémopéritoine</span> — rechercher en <span class=\"kw-alerte\">urgence</span></li><li>Si état clinique le permet → <span class=\"kw-imagerie\">échographie pelvienne</span> confirmant l'<span class=\"kw-def\">hémopéritoine</span></li><li>Si instabilité majeure → <span class=\"kw-ttt\">chirurgie en urgence directe</span> (pas d'attente de l'imagerie)</li></ul><p><strong>Hémopéritoine massif <span class=\"q\">— <span class=\"kw-alerte\">rupture</span> tubaire GEU ou hémorragie de kyste</span></strong></p><p><span class=\"kw-ttt\">Cœlioscopie</span> hémostase en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-ttt\">salpingectomie</span> ou <span class=\"kw-ttt\">salpingotomie</span> selon contexte)</p><ul><li><span class=\"kw-alerte\">Pronostic vital</span> engagé immédiatement</li><li><span class=\"kw-bio\">β-hCG</span> positif → <span class=\"kw-alerte\">rupture</span> de <span class=\"kw-def\">GEU</span> jusqu'à preuve du contraire</li></ul><p><strong>Torsion d'annexe <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> vasculaire ovarienne</span></strong></p><p><span class=\"kw-ttt\">Cœlioscopie</span> de détorsion en <span class=\"kw-chiffre\">&lt; 6–8 h</span> (conservation ovarienne si possible)</p><ul><li>Risque de <span class=\"kw-alerte\">nécrose ovarienne</span> irréversible au-delà de <span class=\"kw-chiffre\">6–8 h</span></li><li>Douleur <span class=\"kw-clinique\">brutale</span>, très intense, résistant aux <span class=\"kw-ttt\">antalgiques</span> de palier III</li></ul>","hospit":"<p><strong>Circuit chirurgical immédiat :</strong> <span class=\"kw-alerte\">instabilité hémodynamique</span> ou <span class=\"kw-alerte\">hémopéritoine</span> confirmé → bloc opératoire sans délai.<br><strong>Médical ambulatoire :</strong> <span class=\"kw-def\">IGH</span> simple (<span class=\"kw-clinique\">apyrexie</span>, absence de <span class=\"kw-alerte\">défense</span>, pas d'<span class=\"kw-def\">ATO</span>) → <span class=\"kw-ttt\">antibiothérapie</span> orale en ambulatoire.<br><strong><span class=\"kw-alerte\">Hospitalisation</span> médicale :</strong> <span class=\"kw-def\">IGH</span> compliquée (<span class=\"kw-def\">ATO</span>, <span class=\"kw-clinique\">fièvre</span> élevée, <span class=\"kw-alerte\">irritation péritonéale</span>) → <span class=\"kw-ttt\">antibiothérapie</span> <span class=\"kw-ttt\">IV</span> + <span class=\"kw-def\">surveillance</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Instabilité hémodynamique</span> : <span class=\"kw-clinique\">tachycardie</span> &gt;<span class=\"kw-chiffre\"> 100 bpm</span> et/ou <span class=\"kw-clinique\">PA systolique</span> &lt; <span class=\"kw-chiffre\">90 mmHg</span></li><li><span class=\"kw-bio\">β-hCG</span> positif avec <span class=\"kw-alerte\">défense abdominale</span> ou <span class=\"kw-alerte\">contracture</span> → <span class=\"kw-def\">rupture de GEU</span> avec hémopéritoine</li><li><span class=\"kw-clinique\">Scapulalgie</span> (<span class=\"kw-clinique\">irradiation</span> en épaule) → <span class=\"kw-alerte\">épanchement intrapéritonéal</span> compressif</li><li><span class=\"kw-alerte\">Irritation péritonéale</span> généralisée : <span class=\"kw-clinique\">défense diffuse</span> ou <span class=\"kw-clinique\">contracture</span> → torsion compliquée, pelvipéritonite</li><li><span class=\"kw-alerte\">Anémie aiguë</span> clinique (pâleur, <span class=\"kw-clinique\">lipothymie</span>) → saignement actif intrapéritonéal</li></ul>"},"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Instabilité ou syndrome péritonéal ?","detail":"<ul><li>Constantes, douleur, saignement, fièvre et grossesse possible.</li></ul>","branches":[{"label":"Oui","to":"urgent"},{"label":"Non","to":"grossesse"}]},{"id":"urgent","kind":"urgent","label":"Évaluation gynécologique/chirurgicale immédiate","detail":"<ul><li>Réanimation si nécessaire ; ne pas retarder pour terminer tous les examens.</li></ul>","branches":[]},{"id":"grossesse","kind":"decision","label":"Test de grossesse et examen consenti","detail":"<ul><li>β-hCG selon contexte ; échographie pelvienne adaptée.</li></ul>","branches":[{"label":"Grossesse possible/positive","to":"geu"},{"label":"Négative","to":"orientation"}]},{"id":"geu","kind":"urgent","label":"Localiser la grossesse","detail":"<ul><li>GEU jusqu’à exclusion selon contexte ; urgences si aggravation.</li></ul>","branches":[]},{"id":"orientation","kind":"decision","label":"Quelle hypothèse domine ?","detail":"<ul><li>Douleur brutale unilatérale, fièvre/leucorrhées, symptômes urinaires ou digestifs.</li></ul>","branches":[{"label":"Torsion suspectée","to":"torsion"},{"label":"Infection génitale","to":"infection"},{"label":"Autre cause","to":"autre"}]},{"id":"torsion","kind":"urgent","label":"Avis chirurgical urgent","detail":"<ul><li>Un Doppler conservé n’exclut pas une torsion.</li></ul>","branches":[]},{"id":"infection","kind":"finish","label":"Prélèvements et antibiothérapie adaptée","detail":"<ul><li>Rechercher abcès, sepsis, grossesse ; hospitaliser selon gravité.</li></ul>","branches":[]},{"id":"autre","kind":"finish","label":"Bilan orienté sans fermer le diagnostic","detail":"<ul><li>Kyste compliqué, appendicite, cause urinaire ou digestive ; réévaluer.</li></ul>","branches":[]}]},"cards":[{"i":"8767fb7d18ac","n":40,"o":"40-1","u":"Définition","t":"Connaître la définition de la douleur pelvienne aiguë (DPA) et chronique (DPC)","q":"Comment définit-on une douleur pelvienne aiguë (DPA) chez la femme ?","a":"<div class=\"notion-course\"><p>Une douleur pelvienne aiguë (DPA) correspond à une douleur pelvienne de <strong>moins de 1 mois</strong> d'évolution. Elle se caractérise par un <strong>début récent et rapide</strong>.</p></div>"},{"i":"c86add6004f7","n":40,"o":"40-1","u":"Définition","t":"Connaître la définition de la douleur pelvienne aiguë (DPA) et chronique (DPC)","q":"Comment définit-on une douleur pelvienne chronique (DPC) chez la femme ?","a":"<div class=\"notion-course\"><p>Une douleur <span class=\"nc-red nc-bold\">pelvienne</span> chronique (DPC) est une douleur <span class=\"nc-red nc-bold\">pelvienne</span> qui dure depuis <strong>plus de 6 mois</strong>. Elle peut être <strong>permanente ou intermittente</strong>, et cyclique ou non.</p></div>"},{"i":"f08839bba2bd","n":40,"o":"40-1","u":"Définition","t":"Connaître la définition de la douleur pelvienne aiguë (DPA) et chronique (DPC)","q":"Quelle est la définition générale des algies pelviennes chez la femme ?","a":"<div class=\"notion-course\"><p>Les algies pelviennes regroupent l'ensemble des symptômes douloureux, spontanés ou provoqués, siégeant dans la région de l'<strong><span class=\"nc-blue_bg\">hypogastre</span></strong> et/ou des <strong><span class=\"nc-blue_bg\">fosses iliaques</span> droite et gauche</strong>.</p></div>"},{"i":"068157375fb2","n":40,"o":"40-2","u":"Étiologies","t":"Connaître les étiologies des DPA","q":"Quelles sont les étiologies des douleurs pelviennes aiguës (DPA) en lien avec la grossesse ou le post-partum ?","a":"<div class=\"notion-course\">Les étiologies des DPA en lien avec la grossesse ou le post-partum incluent :\n<ul>\n<li>La <strong>grossesse extra-utérine (GEU)</strong>.</li>\n<li>La <strong>fausse couche spontanée</strong>.</li>\n<li>La <strong>rétention post-fausse couche</strong>.</li>\n<li>L'<strong>endométrite du post-partum ou post-abortum</strong>.</li>\n<li>Les <strong>complications du corps jaune gestationnel</strong> (hémorragique, kyste et ses complications).</li>\n</ul></div>"},{"i":"14de6cae27d6","n":40,"o":"40-2","u":"Étiologies","t":"Connaître les étiologies des DPA","q":"Quelles sont les causes urologiques des douleurs pelviennes aiguës (DPA) ?","a":"<div class=\"notion-course\">Les causes urologiques des DPA sont :\n<ul>\n<li>La <strong><span class=\"nc-blue_bg\">colique néphrétique</span></strong>.</li>\n<li>La <strong><span class=\"nc-orange_bg\">pyélonéphrite</span> aiguë (PNA)</strong>.</li>\n<li>Les <strong>infections urinaires (IU) basses</strong>.</li>\n</ul></div>"},{"i":"98e281be9b54","n":40,"o":"40-2","u":"Étiologies","t":"Connaître les étiologies des DPA","q":"Quelles sont les étiologies annexielles des douleurs pelviennes aiguës (DPA) ?","a":"<div class=\"notion-course\">Les étiologies annexielles des DPA sont :\n<ul>\n<li>La <strong>torsion d’annexe</strong>.</li>\n<li>Les <strong><span class=\"nc-red_bg\">complications de kyste ovarien</span></strong> (hémorragie intra-kystique, rupture, <span class=\"nc-red nc-bold\">torsion</span>).</li>\n<li>La <strong>dysovulation</strong>.</li>\n</ul></div>"},{"i":"cab2ecf39e18","n":40,"o":"40-2","u":"Étiologies","t":"Connaître les étiologies des DPA","q":"Quelles sont quelques étiologies rares de douleurs pelviennes aiguës (DPA) ?","a":"<div class=\"notion-course\">Parmi les étiologies rares de DPA, on retrouve :\n<ul>\n<li>La <strong>sacro-iléite bactérienne</strong>.</li>\n<li>L'<strong>ostéite pelvienne</strong>.</li>\n<li>L'<strong>anévrisme de l’artère iliaque</strong>.</li>\n<li>L'<strong>infection d’un kyste de l’ouraque</strong>.</li>\n</ul></div>"},{"i":"cbdcede11b67","n":40,"o":"40-2","u":"Étiologies","t":"Connaître les étiologies des DPA","q":"Quelles sont les causes infectieuses des douleurs pelviennes aiguës (DPA) ?","a":"<div class=\"notion-course\">Les causes infectieuses des DPA sont :\n<ul>\n<li>Les <strong>Infections Génitales Hautes (IGH)</strong> telles que salpingite, endométrite, pelvipéritonite, <span class=\"nc-red nc-bold\">abcès tubo-ovarien</span>.</li>\n<li>L'<strong>appendicite aiguë</strong>.</li>\n<li>La <strong><span class=\"nc-orange_bg\">pyélonéphrite</span> aiguë (PNA)</strong>.</li>\n<li>Les <strong>infections urinaires (IU) basses</strong>.</li>\n</ul></div>"},{"i":"d7f893b23bb5","n":40,"o":"40-2","u":"Étiologies","t":"Connaître les étiologies des DPA","q":"Quelles sont les étiologies des douleurs pelviennes aiguës (DPA) en cas de présence d'un fibrome utérin ?","a":"<div class=\"notion-course\">En présence d'un fibrome utérin, les étiologies des DPA peuvent être :\n<ul>\n<li>La <strong>nécrobiose aiguë</strong> du fibrome.</li>\n<li>La <strong>torsion d’un myome sous-séreux pédiculé</strong>.</li>\n<li>L'<strong>accouchement d’un myome sous-muqueux</strong> par le col utérin.</li>\n</ul></div>"},{"i":"79c52de61ba6","n":40,"o":"40-4","u":"Diagnostic positif","t":"Connaitre les élements de l’interrogatoire et de l’examen clinique utiles au diagnostic des DPA","q":"Quelle est la triade d'examens complémentaires de première ligne à réaliser chez toute femme en âge de procréer présentant une douleur pelvienne aiguë ?","a":"<div class=\"notion-course\"><p>Chez toute femme en âge de procréer avec une douleur pelvienne aiguë, la triade d'examens de première ligne à réaliser pour éliminer les 4 urgences est :</p><ul><li>Dosage plasmatique des <strong>β-hCG</strong>.</li><li><strong>Bandelette Urinaire (BU)</strong>.</li><li><strong>Échographie pelvienne</strong>.</li></ul></div>"},{"i":"cc01d7e75d8d","n":40,"o":"40-4","u":"Diagnostic positif","t":"Connaitre les élements de l’interrogatoire et de l’examen clinique utiles au diagnostic des DPA","q":"Quels sont les éléments à rechercher lors de l'examen clinique d'une patiente présentant des douleurs pelviennes ?","a":"<div class=\"notion-course\"><p>L'examen clinique doit comporter :</p><ul><li>L'<strong>inspection et palpation abdominale</strong> : recherche de défense, contracture, masse.</li><li>L'examen au <strong>spéculum</strong> : recherche de leucorrhées, <span class=\"nc-blue nc-bold\">métrorragies</span>, évaluation de l'aspect du col.</li><li>Le <strong>toucher vaginal (TV)</strong> :</li><ul><li>Recherche de <strong>douleur à la mobilisation utérine</strong> (orientant vers une Infection Génitale Haute - <span class=\"nc-yellow_bg\">IGH</span>).</li><li>Recherche de <strong>masse latéro-utérine</strong> (orientant vers une Grossesse Extra-Utérine - GEU ou un kyste compliqué).</li><li>Recherche de <strong>sensibilité du cul-de-sac de Douglas</strong> (orientant vers un hémopéritoine ou une IGH).</li><li>Recherche d'<strong>hypersensibilité de la paroi vaginale antérieure</strong> (orientant vers un syndrome douloureux vésical).</li></ul><li>Une <strong>Bandelette Urinaire (BU) systématique</strong> : recherche de nitrites, leucocytes, hématurie.</li></ul></div>"},{"i":"d944f6c9c16f","n":40,"o":"40-4","u":"Diagnostic positif","t":"Connaitre les élements de l’interrogatoire et de l’examen clinique utiles au diagnostic des DPA","q":"Quels sont les éléments clés de l'interrogatoire à recueillir face à une douleur pelvienne chronique chez la femme ?","a":"<div class=\"notion-course\"><p>Face à une douleur pelvienne chronique (évolution <span class=\"nc-pink nc-bold\">&gt; 6 mois</span>), les éléments clés de l'interrogatoire sont :</p><ul><li>L'<strong>évolution</strong> : permanente ou intermittente.</li><li>L'<strong>apparition dans le cycle</strong> : prémenstruel, dysménorrhée, intermenstruel.</li><li>Le <strong>type</strong> : pesanteur, tiraillement, picotement, avec ou sans irradiation.</li><li>Les <strong>signes associés</strong> :</li><ul><li>Céphalées, lombalgies.</li><li>Diarrhées, constipation.</li><li>Métrorragies, dyspareunies.</li><li>Infertilité.</li></ul><li>Les <strong>antécédents</strong> : gynécologiques, obstétricaux, chirurgicaux, contraception orale (CO).</li><li>Le <strong>retentissement sur la qualité de vie</strong>.</li></ul></div>"},{"i":"fa1d45b26858","n":40,"o":"40-4","u":"Diagnostic positif","t":"Connaitre les élements de l’interrogatoire et de l’examen clinique utiles au diagnostic des DPA","q":"Quels sont les éléments clés de l'interrogatoire à recueillir face à une douleur pelvienne aiguë chez la femme ?","a":"<div class=\"notion-course\"><p>Face à une douleur pelvienne aiguë, les éléments clés de l'interrogatoire sont :</p><ul><li>La <strong>date d'apparition</strong> : récente (&lt; 1 mois), subite.</li><li>L'<strong>évolution</strong> : rapide.</li><li>Le <strong>type</strong> : coup de poignard, torsion, colique, avec ou sans irradiation.</li><li>Les <strong>signes associés</strong> :</li><ul><li>Date des dernières règles, signes de grossesse, <span class=\"nc-blue nc-bold\">métrorragies</span>.</li><li>Signes d'infection (mètreurragies purulentes, fièvre, frissons).</li><li>Nausées, vomissements.</li><li>Signes urinaires (SFU).</li><li>Position antalgique.</li></ul><li>Les <strong>antécédents</strong> : gynécologiques, obstétricaux (GOB), chirurgicaux.</li><li>La <strong>contraception</strong> et les <strong>conduites à risque d'IST</strong>.</li></ul></div>"},{"i":"5c58b05d2e39","n":40,"o":"40-6","u":"Identifier une urgence","t":"Connaître les urgences chirurgicales devant une douleur aiguë pelvienne","q":"Quels sont les éléments clés de l'interrogatoire et de l'examen clinique orientant vers une Rupture hémorragique de kyste ovarien ?","a":"<div class=\"notion-course\">À l'interrogatoire, la patiente rapporte des <strong>douleurs brutales et intenses</strong>, pouvant être associées à une <strong>scapulalgie</strong>. Il est important de rechercher des antécédents de kyste ovarien connu.\nÀ l'examen clinique, on peut observer une <strong>défense abdominale</strong>, voire une contracture. Au toucher vaginal, on retrouve une <strong>douleur diffuse</strong> et un cul-de-sac de Douglas comblé.</div>"},{"i":"7867b93b50c3","n":40,"o":"40-6","u":"Identifier une urgence","t":"Connaître les urgences chirurgicales devant une douleur aiguë pelvienne","q":"Quels sont les signes cliniques et paracliniques suggestifs d'une Infection Génitale Haute (IGH) ?","a":"<div class=\"notion-course\">Cliniquement, une IGH se caractérise par :\n<ul>\n<li>Des <strong>douleurs pelviennes modérées d’installation lente</strong> (évocatrice si &gt; 4 jours), pouvant irradier vers la région lombaire ou l'hypocondre droit.</li>\n<li>Un <strong>syndrome infectieux</strong> (fièvre, frissons).</li>\n<li>Des leucorrhées abondantes, épaisses, jaunâtres et/ou purulentes.</li>\n<li>Des <span class=\"nc-blue nc-bold\">métrorragies</span> peuvent survenir.</li>\n<li>À l'examen vaginal : <strong>douleur ++ à la mobilisation utérine et au cul-de-sac de Douglas</strong>, douleur <span class=\"nc-red nc-bold\">bilatérale</span> à la palpation des annexes.</li>\n</ul>\nParacliniquement :\n<ul>\n<li>La <strong>NFS</strong> montre un syndrome inflammatoire biologique (SIB).</li>\n<li>La <strong>bactériologie</strong> recherche des IST (gonocoque, <i>C. trachomatis</i>, <i>M. genitalium</i>).</li>\n</ul></div>"},{"i":"7f4b99e59d5c","n":40,"o":"40-6","u":"Identifier une urgence","t":"Connaître les urgences chirurgicales devant une douleur aiguë pelvienne","q":"Quels sont les cinq diagnostics qui doivent être systématiquement évoqués devant toute douleur pelvienne aiguë chez une femme en raison de leur pronostic vital et/ou fonctionnel ?","a":"<div class=\"notion-course\">Les cinq diagnostics à évoquer systématiquement sont :\n<ul>\n<li>La <strong>Grossesse Extra-Utérine (GEU)</strong></li>\n<li>La <strong>Torsion d’annexe</strong></li>\n<li>La <strong>Rupture hémorragique de kyste</strong> (avec <span class=\"nc-red nc-bold\">hémopéritoine</span>)</li>\n<li>L'<strong>Infection Génitale Haute (IGH)</strong></li>\n<li>L'<strong>Appendicite aiguë</strong></li>\n</ul></div>"},{"i":"e2ae02109de3","n":40,"o":"40-6","u":"Identifier une urgence","t":"Connaître les urgences chirurgicales devant une douleur aiguë pelvienne","q":"Quels sont les signes d'orientation diagnostique à l'examen clinique et aux examens complémentaires pour une Torsion d'annexe ?","a":"<div class=\"notion-course\">À l'examen clinique, on retrouvera :\n<ul>\n<li>Une <strong>défense abdominale</strong>, éventuellement un météorisme.</li>\n<li>Au toucher vaginal, une <strong>douleur latéro-utérine <span class=\"nc-red nc-bold\">unilatérale</span> très douloureuse au niveau du collet utérin</strong>.</li>\n</ul>\nAux examens complémentaires, l'<strong>échographie pelvienne</strong> montrera :\n<ul>\n<li>Un <strong>ovaire augmenté de taille</strong>, éventuellement un kyste associé.</li>\n<li>Des <strong>anomalies de vascularisation</strong> avec, de manière caractéristique, une disparition du pédicule ovarien au Doppler.</li>\n</ul></div>"},{"i":"f0a285684df2","n":40,"o":"40-6","u":"Identifier une urgence","t":"Connaître les urgences chirurgicales devant une douleur aiguë pelvienne","q":"Quelle est la définition clinique de la Grossesse Extra-Utérine (GEU) et ses signes clés à l'interrogatoire ?","a":"<div class=\"notion-course\">La GEU est une <strong>nidation embryonnaire en dehors de la cavité utérine</strong>. Cliniquement, elle se manifeste par l'association de :\n<ul>\n<li><strong>Douleurs pelviennes aiguës</strong></li>\n<li><strong>Métrorragies « sépia »</strong></li>\n<li>Un <strong>retard de règles</strong></li>\n<li>Des signes sympathiques de grossesse (nausées, tension mammaire) peuvent également être présents.</li>\n</ul></div>"},{"i":"f2f74910e5c4","n":40,"o":"40-6","u":"Identifier une urgence","t":"Connaître les urgences chirurgicales devant une douleur aiguë pelvienne","q":"Quel est le piège classique à connaître devant toute douleur pelvienne aiguë chez une femme en âge de procréer ?","a":"<div class=\"notion-course\">Le piège classique est de ne pas réaliser un dosage sanguin de <strong>β-hCG en urgence</strong>. Il est impératif de le faire quel que soit le contexte contraceptif allégué, car l'absence de β-hCG peut faire manquer un diagnostic crucial, notamment une Grossesse Extra-Utérine (GEU).</div>"},{"i":"3d3f76e38e6c","n":40,"o":"40-7","u":"Définition","t":"Savoir distinguer les douleurs chroniques des douleurs aiguës","q":"Quel piège diagnostique important doit-on avoir à l'esprit concernant les douleurs pelviennes chroniques (DPC) ?","a":"<div class=\"notion-course\"><p>Une DPC peut se <strong>décompenser en phase aiguë</strong> (par exemple, une poussée d'<span class=\"nc-orange_bg\">endométriose</span> ou une <span class=\"nc-red nc-bold\">torsion</span> sur kyste ovarien connu). Il est crucial de se rappeler qu'un terrain chronique <strong>n'élimine jamais une urgence surajoutée</strong>.</p></div>"},{"i":"459a8305e327","n":40,"o":"40-7","u":"Définition","t":"Savoir distinguer les douleurs chroniques des douleurs aiguës","q":"Comment définit-on une douleur pelvienne aiguë (DPA) chez la femme ?","a":"<div class=\"notion-course\"><p>Une douleur pelvienne aiguë (DPA) se caractérise par une durée d'évolution <strong>inférieure à 1 mois</strong>. Son installation est subite et récente, avec une évolution rapide. Le type de douleur est souvent décrit comme un coup de poignard, une <span class=\"nc-red nc-bold\">torsion</span> ou une colique.</p></div>"},{"i":"a0da084dda25","n":40,"o":"40-7","u":"Définition","t":"Savoir distinguer les douleurs chroniques des douleurs aiguës","q":"Comment définit-on une douleur pelvienne chronique (DPC) chez la femme ?","a":"<div class=\"notion-course\"><p>Une douleur pelvienne chronique (DPC) est caractérisée par une durée d'évolution <strong>supérieure à 6 mois</strong>. Son installation est progressive et ancienne, pouvant être cyclique ou non, permanente ou intermittente. Le type de douleur est souvent une pesanteur, un tiraillement ou un picotement.</p></div>"},{"i":"c4cd953db6ba","n":40,"o":"40-7","u":"Définition","t":"Savoir distinguer les douleurs chroniques des douleurs aiguës","q":"Quels sont les enjeux principaux et les causes dominantes à considérer face à une douleur pelvienne aiguë (DPA) et une douleur pelvienne chronique (DPC) ?","a":"<div class=\"notion-course\"><ul><li>Pour une <strong>DPA</strong>, l'enjeu primordial est d'<strong>éliminer une urgence vitale</strong> (par exemple, une grossesse extra-utérine, une <span class=\"nc-red nc-bold\">torsion</span> d'annexe, une infection génitale haute, une appendicite). Les causes dominantes sont principalement <span class=\"nc-orange_bg\">gynécologiques</span>, obstétricales ou chirurgicales aiguës.</li><li>Pour une <strong>DPC</strong>, l'enjeu principal est le <strong>retentissement sur la qualité de vie</strong> de la patiente, avec une <span class=\"nc-red nc-bold\">errance diagnostique</span> fréquente. Les causes dominantes sont plus souvent <span class=\"nc-orange_bg\">digestives</span>, puis <span class=\"nc-orange_bg\">urinaires</span>, et enfin <span class=\"nc-orange_bg\">gynécologiques</span>.</li></ul></div>"},{"i":"43bcf283101a","n":40,"o":"40-8","u":"Définition","t":"Connaître les principales étiologies des DPC","q":"Quelle est la définition des Douleurs Pelviennes Chroniques (DPC) chez la femme ?","a":"<div class=\"notion-course\"><ul><li>Douleurs cycliques : dysménorrhées primaires ou secondaires (<span class=\"nc-orange_bg\">endométriose</span>, adénomyose, obstacle cervical), syndrome prémenstruel et douleur ovulatoire selon contexte.</li><li>Douleurs non cycliques : <span class=\"nc-orange_bg\">endométriose</span>, séquelles d’infection <span class=\"nc-red nc-bold\">pelvienne</span>, pathologie urinaire ou digestive, musculosquelettique et du plancher pelvien ; plusieurs mécanismes peuvent coexister.</li><li>Évaluer symptômes associés, retentissement sexuel, urinaire, digestif et quotidien, traitements antérieurs et facteurs psychosociaux avec respect du consentement.</li><li>L’absence de lésion visible ne permet pas de qualifier automatiquement la douleur de psychogène. Sensibilisation et douleur nociplastique peuvent participer ; une approche multidisciplinaire est utile.</li><li>Toute modification brutale ou signe d’alarme impose de reprendre la démarche de douleur aiguë. Le schéma historique LiSA est transcrit avec cette correction explicite.</li></ul></div>"},{"i":"53f1f1573dbf","n":40,"o":"40-8","u":"Définition","t":"Connaître les principales étiologies des DPC","q":"Quelles sont les causes des douleurs pelviennes chroniques cycliques intermenstruelles et des dysménorrhées ?","a":"<div class=\"notion-course\"><ul><li>Douleurs cycliques : dysménorrhées primaires ou secondaires (<span class=\"nc-orange_bg\">endométriose</span>, adénomyose, obstacle cervical), syndrome prémenstruel et douleur ovulatoire selon contexte.</li><li>Douleurs non cycliques : <span class=\"nc-orange_bg\">endométriose</span>, séquelles d’infection <span class=\"nc-red nc-bold\">pelvienne</span>, pathologie urinaire ou digestive, musculosquelettique et du plancher pelvien ; plusieurs mécanismes peuvent coexister.</li><li>Évaluer symptômes associés, retentissement sexuel, urinaire, digestif et quotidien, traitements antérieurs et facteurs psychosociaux avec respect du consentement.</li><li>L’absence de lésion visible ne permet pas de qualifier automatiquement la douleur de psychogène. Sensibilisation et douleur nociplastique peuvent participer ; une approche multidisciplinaire est utile.</li><li>Toute modification brutale ou signe d’alarme impose de reprendre la démarche de douleur aiguë. Le schéma historique LiSA est transcrit avec cette correction explicite.</li></ul></div>"},{"i":"94c2023a2dc9","n":40,"o":"40-8","u":"Définition","t":"Connaître les principales étiologies des DPC","q":"Quelles sont les principales étiologies extra-génitales des Douleurs Pelviennes Chroniques non cycliques ?","a":"<div class=\"notion-course\"><ul><li>Douleurs cycliques : dysménorrhées primaires ou secondaires (<span class=\"nc-orange_bg\">endométriose</span>, adénomyose, obstacle cervical), syndrome prémenstruel et douleur ovulatoire selon contexte.</li><li>Douleurs non cycliques : <span class=\"nc-orange_bg\">endométriose</span>, séquelles d’infection <span class=\"nc-red nc-bold\">pelvienne</span>, pathologie urinaire ou digestive, musculosquelettique et du plancher pelvien ; plusieurs mécanismes peuvent coexister.</li><li>Évaluer symptômes associés, retentissement sexuel, urinaire, digestif et quotidien, traitements antérieurs et facteurs psychosociaux avec respect du consentement.</li><li>L’absence de lésion visible ne permet pas de qualifier automatiquement la douleur de psychogène. Sensibilisation et douleur nociplastique peuvent participer ; une approche multidisciplinaire est utile.</li><li>Toute modification brutale ou signe d’alarme impose de reprendre la démarche de douleur aiguë. Le schéma historique LiSA est transcrit avec cette correction explicite.</li></ul></div>"},{"i":"c19261cc5fd2","n":40,"o":"40-8","u":"Définition","t":"Connaître les principales étiologies des DPC","q":"Quelles sont les principales étiologies génitales organiques des Douleurs Pelviennes Chroniques non cycliques ?","a":"<div class=\"notion-course\"><ul><li>Douleurs cycliques : dysménorrhées primaires ou secondaires (<span class=\"nc-orange_bg\">endométriose</span>, adénomyose, obstacle cervical), syndrome prémenstruel et douleur ovulatoire selon contexte.</li><li>Douleurs non cycliques : <span class=\"nc-orange_bg\">endométriose</span>, séquelles d’infection <span class=\"nc-red nc-bold\">pelvienne</span>, pathologie urinaire ou digestive, musculosquelettique et du plancher pelvien ; plusieurs mécanismes peuvent coexister.</li><li>Évaluer symptômes associés, retentissement sexuel, urinaire, digestif et quotidien, traitements antérieurs et facteurs psychosociaux avec respect du consentement.</li><li>L’absence de lésion visible ne permet pas de qualifier automatiquement la douleur de psychogène. Sensibilisation et douleur nociplastique peuvent participer ; une approche multidisciplinaire est utile.</li><li>Toute modification brutale ou signe d’alarme impose de reprendre la démarche de douleur aiguë. Le schéma historique LiSA est transcrit avec cette correction explicite.</li></ul></div>"},{"i":"218929100812","n":40,"o":"40-9","u":"Examens complémentaires","t":"Connaître les indications des examens d’imagerie devant une algie pelvienne chez la femme","q":"Quel est le piège classique concernant l'imagerie dans le syndrome douloureux vésical chronique ?","a":"<div class=\"notion-course\"><p>Il ne faut <strong>pas réaliser d'imagerie systématique</strong> (échographie ou scanner) dans le syndrome douloureux vésical chronique. L'examen de référence dans ce contexte est la <strong>cystoscopie</strong>.</p></div>"},{"i":"ab5fa7b3df3b","n":40,"o":"40-9","u":"Examens complémentaires","t":"Connaître les indications des examens d’imagerie devant une algie pelvienne chez la femme","q":"Quelle est la place et les modalités de l'échographie pelvienne dans l'exploration d'une algie pelvienne chez la femme ?","a":"<div class=\"notion-course\"><p>L'<span class=\"nc-blue_bg\">échographie</span> pelvienne est l'<strong>examen-clé de première intention</strong>. Elle doit être réalisée en urgence si instabilité hémodynamique ou suspicion d'<span class=\"nc-red nc-bold\">hémopéritoine</span>. Elle comprend une exploration par <strong>voie abdominale et endovaginale</strong> (sauf chez la femme vierge où seule la voie abdominale est utilisée).</p></div>"},{"i":"b221a3b6cc46","n":40,"o":"40-9","u":"Examens complémentaires","t":"Connaître les indications des examens d’imagerie devant une algie pelvienne chez la femme","q":"Quelles sont les indications de l'échographie des voies urinaires et du TDM abdomino-pelvien en cas d'algie pelvienne chez la femme ?","a":"<div class=\"notion-course\"><ul><li>L'<strong><span class=\"nc-blue_bg\">échographie</span> des voies urinaires</strong> est indiquée si hématurie à la bandelette urinaire, afin de rechercher une <strong><span class=\"nc-blue_bg\">colique néphrétique</span></strong> ou une dilatation des voies urinaires.</li><li>Le <strong>TDM abdomino-pelvien</strong> est indiqué en cas de doute diagnostique entre une infection génitale haute (<span class=\"nc-brown_bg\">IGH</span>) et une appendicite, ou pour la recherche d'une complication comme un abcès.</li></ul></div>"},{"i":"b2238aab2d1f","n":40,"o":"40-9","u":"Examens complémentaires","t":"Connaître les indications des examens d’imagerie devant une algie pelvienne chez la femme","q":"Quelle est la règle EDN concernant les examens complémentaires à réaliser devant une douleur pelvienne aiguë chez une femme en âge de procréer ?","a":"<div class=\"notion-course\"><p>Devant une douleur pelvienne aiguë chez une femme en âge de procréer, la règle EDN est de réaliser systématiquement :</p><ul><li>un dosage des <strong>β-hCG</strong></li><li>une <strong>bandelette urinaire</strong> (BU)</li><li>une <strong>échographie pelvienne</strong></li></ul></div>"},{"i":"be5c7a29a187","n":40,"o":"40-9","u":"Examens complémentaires","t":"Connaître les indications des examens d’imagerie devant une algie pelvienne chez la femme","q":"Quels signes échographiques l'échographie pelvienne peut-elle révéler dans le cadre d'une algie pelvienne chez la femme pour une grossesse extra-utérine, une torsion d'annexe ou une infection génitale haute (IGH) ?","a":"<div class=\"notion-course\"><ul><li>En cas de <strong>grossesse extra-utérine (GEU)</strong> : <strong>vacuité utérine</strong>, masse latéro-utérine, épanchement de Douglas.</li><li>En cas de <strong>torsion d'annexe</strong> : ovaire augmenté de taille (± kyste associé), <strong>arrêt des flux au Doppler</strong>.</li><li>En cas d'<strong>infection génitale haute (<span class=\"nc-brown_bg\">IGH</span>)</strong> : <span class=\"nc-blue_bg\">épaississement de la paroi tubaire</span>, épanchement intra-tubaire, <span class=\"nc-red nc-bold\">abcès tubo-ovarien</span>.</li></ul></div>"},{"i":"ff706d8e6683","n":40,"o":"40-9","u":"Examens complémentaires","t":"Connaître les indications des examens d’imagerie devant une algie pelvienne chez la femme","q":"Dans quelles situations l'IRM pelvienne et la cœlioscopie sont-elles indiquées pour une algie pelvienne chez la femme ?","a":"<div class=\"notion-course\"><ul><li>L'<strong>IRM pelvienne</strong> est indiquée en cas de <strong>doutes diagnostiques persistants</strong>, notamment chez la femme enceinte pour éviter l'irradiation.</li><li>La <strong>cœlioscopie</strong> (diagnostique et thérapeutique) est indiquée en cas de doute diagnostique persistant après bilan non invasif, ou s'il existe une indication chirurgicale claire (comme une torsion d'annexe, une <span class=\"nc-orange_bg\">GEU</span> ou un <span class=\"nc-red nc-bold\">abcès tubo-ovarien</span> - ATO).</li></ul></div>"},{"i":"7c6eb2022572","n":40,"o":"40-3","u":"Physiopathologie","t":"Connaître la physiopathologie des DPA et des DPC","q":"Que retenir concernant la physiopathologie des DPA et des DPC ?","a":"<div class=\"notion-course\"><p>La <span>physiopathologie</span> diffère entre douleur aiguë (mécanisme lésionnel direct) et douleur chronique (mécanismes multiples intriqués).</p>\n\n      <h4>Douleur pelvienne aiguë — voies de la douleur</h4>\n      <p>L’interprétation sémiologique est <strong>difficile</strong> : proximité des organes pelviens + innervation commune. Trois plexus efférents structurent la topographie :</p>\n      <table>\n        <thead>\n          <tr><th>Plexus</th><th>Organes</th><th>Topographie de la douleur</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Hypogastrique</strong></td>\n            <td><span class=\"nc-yellow_bg\">Corps utérin</span>, <span class=\"nc-yellow_bg\">1/3 proximal des trompes</span>, <span class=\"nc-yellow_bg\">ligament large</span>, <span class=\"nc-yellow_bg\">calotte vésicale</span></td>\n            <td>Hypogastrique</td>\n          </tr>\n          <tr>\n            <td><strong>Aortique</strong></td>\n            <td><span class=\"nc-purple_bg\">Ovaires</span>, <span class=\"nc-purple_bg\">portion distale des trompes</span>, uretères rétro-ligamentaires</td>\n            <td><span class=\"nc-purple_bg\">Flancs</span>, <span><span class=\"nc-blue_bg\">fosses iliaques</span></span>, <span class=\"nc-purple_bg\">fosses lombaires</span></td>\n          </tr>\n          <tr>\n            <td><strong>Pelvien</strong></td>\n            <td><span class=\"nc-blue_bg\">Vagin</span>, col/isthme, ligaments utéro-sacrés, <span class=\"nc-blue_bg\">bas uretères</span>, <span class=\"nc-blue_bg\">trigone vésical</span>, <span class=\"nc-blue_bg\">cul-de-sac de Douglas</span>, recto-sigmoïde</td>\n            <td><strong><span class=\"nc-red nc-bold\">Sacrée</span></strong> et <strong><span class=\"nc-red nc-bold\">périnéale</span></strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Douleur pelvienne chronique — hypothèses physiopathologiques</h4>\n      <ul>\n        <li><strong>Hypothèse <span>ischémique</span></strong> : les <span><span class=\"nc-pink nc-bold\">prostaglandines</span></span> ↗ les <span class=\"nc-blue_bg\">contractions utérines</span> → ischémie utérine relative douloureuse</li>\n        <li><strong>Hypothèse spasmodique</strong> : les <span>prostaglandines</span> ↗ le tonus du sphincter cervico-isthmique, désynchronisé du cycle → retard d’ouverture du col → gêne à l’écoulement menstruel</li>\n        <li><strong>Hypothèse congestive</strong> : <span class=\"nc-red nc-bold\">stase</span> <span class=\"nc-red nc-bold\">pelvienne</span> (<span><span class=\"nc-blue_bg\">constipation</span></span>, faiblesse musculaire <span class=\"nc-red nc-bold\">pelvienne</span>, <span class=\"nc-blue_bg\">varices pelviennes</span>)</li>\n        <li><strong>Facteurs hormonaux</strong> : déséquilibre œstroprogestatif en phase lutéale (hyperœstrogénie relative) → congestion ; pics et chutes d’œstrogènes expliquent les douleurs intermenstruelles et prémenstruelles</li>\n        <li><strong>Facteurs psychologiques</strong> : zone pelvi-génitale = site fréquent de somatisation → rôle dans le <strong>maintien</strong> de la douleur chronique</li>\n      </ul></div>"},{"i":"4fc31074092e","n":40,"o":"40-5","u":"Examens complémentaires","t":"Connaître les examens complémentaires biologiques","q":"Que retenir concernant les examens complémentaires biologiques ?","a":"<div class=\"notion-course\"><p>Toute femme en âge de procréer avec une <span>douleur pelvienne aiguë</span> bénéficie d’un bilan <span>biologique</span> de <strong>1ʳᵉ intention</strong> centré sur l’élimination des urgences.</p>\n\n      <div class=\"callout callout-info\">\n        <strong>Réflexe 1ʳᵉ intention.</strong> <span><span class=\"nc-pink_bg\">β-hCG</span></span> + <span>NFS</span> + <span>CRP</span> + <span>BU</span> + <span>prélèvements vaginaux</span>/endocervicaux (si suspicion d’<span class=\"nc-red\">IGH</span>).\n      </div>\n\n      <table>\n        <thead>\n          <tr><th>Examen</th><th>Intérêt · interprétation</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>β-hCG</span></strong></td>\n            <td>Indispensable chez toute femme en période d’activité génitale · <strong>si négatif → élimine une GEU</strong></td>\n          </tr>\n          <tr>\n            <td><strong><span>NFS</span></strong></td>\n            <td>\n              <strong>Anémie</strong> → hémopéritoine<br>\n              Hyperleucocytose : quasi-constante dans l’appendicite · <strong>fréquemment absente dans l’<span class=\"nc-brown_bg\">IGH</span> simple</strong> (si présente → forme compliquée) · fréquente sur nécrobiose · rare sur <span class=\"nc-brown_bg\">torsion d’annexe</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>CRP</span></strong></td>\n            <td><span>Syndrome <span>inflammatoire</span></span> → cause infectieuse (IGH, appendicite) · <span>CRP</span> très élevée + IGH → évoque un <span><span class=\"nc-red nc-bold\">abcès tubo-ovarien</span></span></td>\n          </tr>\n          <tr>\n            <td><strong><span>Bandelette urinaire</span></strong></td>\n            <td>Nitrites + <span>leucocyturie</span> → <strong>infection urinaire</strong> · <span>hématurie</span> → <span class=\"nc-blue_bg\">colique néphrétique</span> (impose une écho des voies urinaires)</td>\n          </tr>\n          <tr>\n            <td><strong>Bactériologie</strong></td>\n            <td>Prélèvements vaginaux + endocervicaux : <strong>indispensables si suspicion d’<span class=\"nc-red\">IGH</span></strong> (<span>gonocoque</span>, <em>C. trachomatis</em>, <em>M. genitalium</em>) · ablation + mise en culture du DIU si <span class=\"nc-red\">IGH</span></td>\n          </tr>\n          <tr>\n            <td><strong><span>Biopsie d’endomètre</span></strong><br><em>(2ᵈᵉ intention)</em></td>\n            <td>Doute <span><span class=\"nc-red\">grossesse</span></span><span class=\"nc-red\"> arrêtée</span> / <span class=\"nc-red\">GEU</span> → présence de <em>villosités choriales</em> élimine la <span class=\"nc-red\">GEU</span> · suspicion d’<span class=\"nc-red\">IGH</span> paucisymptomatique → <span class=\"nc-blue_bg\">signes histologiques d’endométrite</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège ⭐.</strong> <em>Aucun examen <span>biologique</span> n’affirme le syndrome douloureux vésical chronique</em> : l’<span>ECBU</span> y est <strong>stérile</strong> (<span>leucocyturie</span> possible) — le diagnostic est endoscopique (<span>cystoscopie</span>), traité en onglet « Astuces PU ».\n      </div></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d94181b08bb7ddee38922384?pvs=204","reviewedAt":"2026-10-15","note":"Cours personnel, couleurs des passages Notion correspondants, corrections et parcours interactifs sourcés. Les compléments sont distingués des figures d’origine."},"liensGlobaux":[{"href":"https://cego-obgyn.fr/deuxieme-cycle/","label":"Collège CNGOF–CEGO · Référentiel, 6e édition 2024"},{"href":"https://cngof.fr/app/uploads/2025/11/Endometriose202025_imagerie_recommandations_ca.pdf","label":"HAS–CNGOF · Imagerie de l’endométriose, 2025"}]};
